def register_closest_photos_callback(app):
    """Register callback for finding closest photos by text description.

    This callback:
    1. Takes a text query from the user
    2. Generates an embedding vector for the query text
    3. Performs vector similarity search within the current folder
    4. Returns top 10 matching photos
    """
    @app.callback(
        Output("closest-photos-results", "children"),
        Output("closest-photos-status", "children"),
        Input("btn-find-closest-photos", "n_clicks"),
        State("closest-photos-input", "value"),
        State("input-folder", "value"),
        prevent_initial_call=True,
    )
    def find_closest_photos(n_clicks, query, folder):
        if not n_clicks or not query or not folder:
            return dash.no_update, dash.no_update

        # Check if vector search library is available
        vec_service = get_vector_search_service()
        if not vec_service.is_available:
            return (
                html.Div(),
                dbc.Alert(
                    f"sqlite-vec library is not available. {vec_service.not_available_message}",
                    color="danger",
                    dismissable=True,
                ),
            )

        try:
            # Get config
            config = AppConfig.from_env()

            # Get database
            db = _get_db(folder)
            if db is None:
                return (
                    html.Div(),
                    dbc.Alert(
                        "No features.db found for this folder. Process the folder first.",
                        color="warning",
                        dismissable=True,
                    ),
                )

            # Initialize vector search
            db.init_vector_search()

            # Generate embedding for the query text
            generator = create_generator(
                backend=config.embedding_backend,
                host=config.llm_host,
                port=config.llm_port,
                model=config.embedding_model,
                timeout=config.timeout,
            )

            query_embedding = generator.generate_from_text(query)
            if query_embedding is None:
                return (
                    html.Div(),
                    dbc.Alert(
                        "Failed to generate embedding for the query. Check your embedding model and server.",
                        color="danger",
                        dismissable=True,
                    ),
                )

            # Find similar images (top 10)
            limit = 10
            similar = db.find_similar(query_embedding, limit=limit)
            db.close()

            if not similar:
                return (
                    html.Div("No similar photos found.", className="text-muted"),
                    dbc.Alert("No similar photos found.", color="info", dismissable=True),
                )

            # Build results as photo cards (reusing build_photo_cards)
            # Convert similar results to the format expected by build_photo_cards
            results = []
            for image_path, score in similar:
                results.append({
                    "image_path": image_path,
                    "similarity_score": score,
                })

            # Use a custom display for closest photos results with scores
            items = []
            for image_path, score in similar:
                filename = os.path.basename(image_path)
                preview_url = _preview_url(image_path, folder, size="thumb")
                score_pct = score * 100

                items.append(
                    dbc.Col(
                        html.Div(
                            [
                                html.Img(
                                    src=preview_url,
                                    style={"maxWidth": "140px", "maxHeight": "140px", "objectFit": "cover", "pointerEvents": "none", "userSelect": "none"},
                                    className="img-thumbnail",
                                    title=filename,
                                    draggable="false",
                                ),
                                html.Small(
                                    [
                                        html.Strong(f"{score_pct:.1f}% "),
                                        html.Span(filename, className="text-muted"),
                                    ],
                                    className="d-block text-center mt-1",
                                ),
                            ],
                            id={"type": "thumbnail", "source": "closest", "index": image_path},
                            n_clicks=0,
                            style={"cursor": "pointer", "userSelect": "none"},
                            className="text-center mb-3",
                        ),
                        width="auto",
                    )
                )

            return (
                dbc.Row(items, className="g-2 flex-wrap"),
                dbc.Alert(
                    f"Found {len(similar)} similar photo(s) for: '{query}'",
                    color="success",
                    dismissable=True,
                ),
            )

        except Exception as e:
            logger.error("Failed to find closest photos: %s", e)
            return (
                html.Div(),
                dbc.Alert(
                    f"Error finding closest photos: {str(e)}",
                    color="danger",
                    dismissable=True,
                ),
            )


def register_clear_closest_photos_callback(app):
